const rawInput = $input.first().json.body || $input.first().json || {};
const rawFrom = rawInput.from;
const rawMensagem = rawInput.mensagem;

if (!rawFrom || !rawMensagem || typeof rawMensagem !== 'string' || rawMensagem.trim().length === 0) {
  return [{ json: { isValid: false, errorCode: 'INVALID_PAYLOAD', errorMessage: "Os campos 'from' e 'mensagem' sao obrigatorios.", received: rawInput } }];
}

const usuario = String(rawFrom).replace(/\D/g, '') || String(rawFrom).trim();

return [{ json: { isValid: true, usuario, mensagemOriginal: rawMensagem.trim(), receivedAt: new Date().toISOString() } }];

const mensagem = $json.mensagemOriginal;
const body = {
  model: "gpt-4o-mini",
  temperature: 0.2,
  response_format: { type: "json_object" },
  messages: [
    {
      role: "system",
      content: "Voce e o motor de IA de triagem semantica de WhatsApp da PSA (Profissionais SA). Analise a mensagem do cliente e classifique com precisao em uma das 4 intencoes: SUPORTE_URGENTE (problemas, reclamacoes, urgencias, produto danificado, entrega atrasada), COMERCIAL_VENDAS (interesse em compra, precos, orcamentos, catalogo, planos), CANCELAMENTO (cancelar contrato, reembolso, estorno, desistir), DUVIDA_GERAL (outras duvidas e perguntas gerais). Responda EXCLUSIVAMENTE com JSON: {\"intencao\": string, \"confianca\": number, \"resumo\": string, \"resposta\": string}. O campo resposta deve ser uma mensagem empatica e profissional em portugues para enviar ao cliente."
    },
    {
      role: "user",
      content: mensagem
    }
  ]
};
return [{ json: { ...($json), openaiBody: JSON.stringify(body) } }];

const httpResp = $input.first().json;
let aiResult = {};
try {
  const raw = httpResp.choices[0].message.content;
  aiResult = JSON.parse(raw);
} catch(e) {
  aiResult = { intencao: 'DUVIDA_GERAL', confianca: 0.5, resumo: 'Falha ao parsear IA', resposta: 'Mensagem recebida. Em breve entraremos em contato.' };
}

const validado = $('Code - Validacao Defensiva').first().json;

return [{ json: { usuario: validado.usuario, mensagemOriginal: validado.mensagemOriginal, resposta: aiResult.resposta, intencao: aiResult.intencao, confianca: aiResult.confianca, resumo: aiResult.resumo, motor: 'openai/gpt-4o-mini', receivedAt: validado.receivedAt, processedAt: new Date().toISOString() } }];
